def detect_enc(blob):
    if blob.startswith(b"\xff\xfe"): return "utf-16-le"
    try:
        blob.decode("utf-8"); return "utf-8"
    except UnicodeDecodeError:
        return "latin-1 (fallback)"
for b in ["hello".encode("utf-8"), "caf\xe9".encode("latin-1")]:
    print(detect_enc(b))

